49: /*****************************************************************************/
50: /* initBcg729EncoderChannel : create context structure and initialise it     */
51: /*    return value :                                                         */
52: /*      - the encoder channel context data                                   */
53: /*                                                                           */
54: /*****************************************************************************/
55: bcg729EncoderChannelContextStruct *initBcg729EncoderChannel(uint8_t enableVAD)
56: {
57: 	/* create the context structure */
58: 	bcg729EncoderChannelContextStruct *encoderChannelContext = malloc(sizeof(bcg729EncoderChannelContextStruct));
59: 	memset(encoderChannelContext, 0, sizeof(bcg729EncoderChannelContextStruct));
60: 
61: 	/* initialise statics buffers and variables */
62: 	memset(encoderChannelContext->signalBuffer, 0, (L_LP_ANALYSIS_WINDOW-L_FRAME)*sizeof(word16_t)); /* set to zero all the past signal */
63: 	encoderChannelContext->signalLastInputFrame = &(encoderChannelContext->signalBuffer[L_LP_ANALYSIS_WINDOW-L_FRAME]); /* point to the last frame in the signal buffer */
64: 	encoderChannelContext->signalCurrentFrame = &(encoderChannelContext->signalBuffer[L_LP_ANALYSIS_WINDOW-L_SUBFRAME-L_FRAME]); /* point to the current frame */
65: 	memcpy(encoderChannelContext->previousLSPCoefficients, previousLSPInitialValues, NB_LSP_COEFF*sizeof(word16_t)); /* reset the previous quantized and unquantized LSP vector with the same value */
66: 	memcpy(encoderChannelContext->previousqLSPCoefficients, previousLSPInitialValues, NB_LSP_COEFF*sizeof(word16_t));
67: 	memset(encoderChannelContext->weightedInputSignal, 0, MAXIMUM_INT_PITCH_DELAY*sizeof(word16_t)); /* set to zero values of previous weighted signal */
68: 	memset(encoderChannelContext->excitationVector, 0, L_PAST_EXCITATION*sizeof(word16_t)); /* set to zero values of previous excitation vector */
69: 	memset(encoderChannelContext->targetSignal, 0, NB_LSP_COEFF*sizeof(word16_t)); /* set to zero values filter memory for the targetSignal computation */
70: 	encoderChannelContext->lastQuantizedAdaptativeCodebookGain = O2_IN_Q14; /* quantized gain is initialized at his minimum value: 0.2 */
71: 	if (enableVAD == 1) {
72: 		encoderChannelContext->VADChannelContext = initBcg729VADChannel();
73: 		encoderChannelContext->DTXChannelContext = initBcg729DTXChannel();
74: 	} else {
75: 		encoderChannelContext->VADChannelContext = NULL;
76: 		encoderChannelContext->DTXChannelContext = NULL;
77: 	}
78: 
79: 	/* initialisation of the differents blocs which need to be initialised */
80: 	initPreProcessing(encoderChannelContext);
81: 	initLSPQuantization(encoderChannelContext);
82: 	initGainQuantization(encoderChannelContext);
83: 
84: 	return encoderChannelContext;
85: }
