87: /*****************************************************************************/
88: /* closeBcg729EncoderChannel : free memory of context structure              */
89: /*    parameters:                                                            */
90: /*      -(i) encoderChannelContext : the channel context data                */
91: /*                                                                           */
92: /*****************************************************************************/
93: void closeBcg729EncoderChannel(bcg729EncoderChannelContextStruct *encoderChannelContext)
94: {
95: 	if (encoderChannelContext) {
96: 		if (encoderChannelContext->VADChannelContext) {
97: 			free(encoderChannelContext->VADChannelContext);
98: 		}
99: 		if (encoderChannelContext->DTXChannelContext) {
100: 			free(encoderChannelContext->DTXChannelContext);
101: 		}
102: 		free(encoderChannelContext);
103: 	}
104: }
