106: /*****************************************************************************/
107: /* bcg729Encoder :                                                           */
108: /*    parameters:                                                            */
109: /*      -(i) encoderChannelContext : context for this encoder channel        */
110: /*      -(i) inputFrame : 80 samples (16 bits PCM)                           */
111: /*      -(o) bitStream : The 15 parameters for a frame on 80 bits            */
112: /*           on 80 bits (10 8bits words)                                     */
113: /*                                                                           */
114: /*****************************************************************************/
115: void bcg729Encoder(bcg729EncoderChannelContextStruct *encoderChannelContext, const int16_t inputFrame[], uint8_t bitStream[], uint8_t *bitStreamLength)
116: {
117: 	int i;
118: 	uint16_t parameters[NB_PARAMETERS]; /* the output parameters in an array */
119: 
120: 	/* internal buffers which we do not need to keep between calls */
121: 	word16_t LPCoefficients[NB_LSP_COEFF]; /* the LP coefficients in Q3.12 */
122: 	word16_t LSFCoefficients[NB_LSP_COEFF]; /* the LSF coefficients in Q3.12 */
123: 	word16_t qLPCoefficients[2*NB_LSP_COEFF]; /* the quantized LP coefficients in Q3.12 computed from the qLSP one after interpolation: two sets, one for each subframe */
124: 	word16_t weightedqLPCoefficients[2*NB_LSP_COEFF]; /* the qLP coefficients in Q3.12 weighted according to spec A3.3.3 */
125: 	word16_t LSPCoefficients[NB_LSP_COEFF]; /* the LSP coefficients in Q15 */
126: 	word16_t qLSPCoefficients[NB_LSP_COEFF]; /* the quantized LSP coefficients in Q15 */
127: 	word16_t interpolatedqLSP[NB_LSP_COEFF]; /* the interpolated qLSP used for first subframe in Q15 */
128: 
129: 	uint16_t openLoopPitchDelay;
130: 	int16_t intPitchDelayMin;
131: 	int16_t intPitchDelayMax;
132: 	int subframeIndex;
133: 	int LPCoefficientsIndex = 0;
134: 	int parametersIndex = 4; /* index to insert parameters in the parameters output array */
135: 	word16_t impulseResponseInput[L_SUBFRAME]; /* input buffer for the impulse response computation: in Q12, 1 followed by all zeros see spec A3.5*/
136: 
137: 	/* used for VAD */
138: 	word32_t reflectionCoefficients[NB_LSP_COEFF]; /* in Q31, computed during LP generation, reflectionCoefficients[1] is requested by VAD, the others are stored in context if we cover RFC3389 payload generation */
139: 	word32_t autoCorrelationCoefficients[NB_LSP_COEFF+3]; /* if VAD is enabled we must compute 13 coefficients, 11 otherwise but used only internally by computeLP function in that case */
140: 	word32_t noLagAutoCorrelationCoefficients[NB_LSP_COEFF+3]; /* DTX must have access to autocorrelation Coefficients on which lag windowing as not been applied */
141: 	int8_t autoCorrelationCoefficientsScale; /* autocorrelation coefficients are normalised by computeLP, must get their scaling factor */
142: 
143: 	/*****************************************************************************************/
144: 	/*** on frame basis : preProcessing, LP Analysis, Open-loop pitch search               ***/
145: 	preProcessing(encoderChannelContext, inputFrame, encoderChannelContext->signalLastInputFrame); /* output of the function in the signal buffer */
146: 
147: 	/* use the whole signal Buffer for windowing and autocorrelation */
148: 	/* autoCorrelation Coefficients are computed and used internally, in case of VAD we must compute and retrieve 13 coefficients, compute only 11 when VAD is disabled */
149: 	computeLP(encoderChannelContext->signalBuffer, LPCoefficients, reflectionCoefficients, autoCorrelationCoefficients, noLagAutoCorrelationCoefficients, &autoCorrelationCoefficientsScale, (encoderChannelContext->VADChannelContext != NULL)?(NB_LSP_COEFF+3):(NB_LSP_COEFF+1));
150: 	/*** compute LSP: it might fail, get the previous one in this case ***/
151: 	if (!LP2LSPConversion(LPCoefficients, LSPCoefficients)) {
152: 		/* unable to find the 10 roots repeat previous LSP */
153: 		memcpy(LSPCoefficients, encoderChannelContext->previousLSPCoefficients, NB_LSP_COEFF*sizeof(word16_t));
154: 	}
155: 
156: 	/*********** VAD *****************/
157: 	if (encoderChannelContext->VADChannelContext != NULL) { /* if VAD is not enable, no context */
158: 		uint8_t VADflag = 1;
159: 		/* update DTX context */
160: 		updateDTXContext(encoderChannelContext->DTXChannelContext, noLagAutoCorrelationCoefficients, autoCorrelationCoefficientsScale);
161: 
162: 		/*** compute LSF in Q2.13 : lsf = arcos(lsp) range [0, Pi[ spec 3.2.4 eq18 ***/
163: 		/* TODO : remove it from LSPQuantizationFunction and perform it out of enableVAD test */
164: 		for (i=0; i<NB_LSP_COEFF; i++)  {
165: 			LSFCoefficients[i] = g729Acos_Q15Q13(LSPCoefficients[i]);
166: 		}
167: 
168: 		VADflag = bcg729_vad(encoderChannelContext->VADChannelContext, reflectionCoefficients[1], LSFCoefficients, autoCorrelationCoefficients, autoCorrelationCoefficientsScale, encoderChannelContext->signalCurrentFrame);
169: 
170: 		/* call encodeSIDFrame even if it is a voice frame as it will update DTXContext with current VADflag : TODO : move updateDTXContext in the encodeSIDFrame as part of the update is performed in it anyway */
171: 		encodeSIDFrame(encoderChannelContext->DTXChannelContext,  encoderChannelContext->previousLSPCoefficients, encoderChannelContext->previousqLSPCoefficients, VADflag, encoderChannelContext->previousqLSF, &(encoderChannelContext->excitationVector[L_PAST_EXCITATION]), qLPCoefficients, bitStream, bitStreamLength);
172: 
173: 		if (VADflag == 0 ) { /* NOISE frame has been encoded */
174: 			word16_t residualSignal[L_FRAME];
175: 			/* update encoder context : generate weighted signal */
176: 			/*** Compute the weighted Quantized LP Coefficients according to spec A3.3.3 ***/
177: 			/*  weightedqLPCoefficients[0] = qLPCoefficients[0]*Gamma^(i+1) (i=0..9) with Gamma = 0.75 in Q15 */
178: 			weightedqLPCoefficients[0] = MULT16_16_P15(qLPCoefficients[0], GAMMA_E1);
179: 			weightedqLPCoefficients[1] = MULT16_16_P15(qLPCoefficients[1], GAMMA_E2);
180: 			weightedqLPCoefficients[2] = MULT16_16_P15(qLPCoefficients[2], GAMMA_E3);
181: 			weightedqLPCoefficients[3] = MULT16_16_P15(qLPCoefficients[3], GAMMA_E4);
182: 			weightedqLPCoefficients[4] = MULT16_16_P15(qLPCoefficients[4], GAMMA_E5);
183: 			weightedqLPCoefficients[5] = MULT16_16_P15(qLPCoefficients[5], GAMMA_E6);
184: 			weightedqLPCoefficients[6] = MULT16_16_P15(qLPCoefficients[6], GAMMA_E7);
185: 			weightedqLPCoefficients[7] = MULT16_16_P15(qLPCoefficients[7], GAMMA_E8);
186: 			weightedqLPCoefficients[8] = MULT16_16_P15(qLPCoefficients[8], GAMMA_E9);
187: 			weightedqLPCoefficients[9] = MULT16_16_P15(qLPCoefficients[9], GAMMA_E10);
188: 			weightedqLPCoefficients[10] = MULT16_16_P15(qLPCoefficients[10], GAMMA_E1);
189: 			weightedqLPCoefficients[11] = MULT16_16_P15(qLPCoefficients[11], GAMMA_E2);
190: 			weightedqLPCoefficients[12] = MULT16_16_P15(qLPCoefficients[12], GAMMA_E3);
191: 			weightedqLPCoefficients[13] = MULT16_16_P15(qLPCoefficients[13], GAMMA_E4);
192: 			weightedqLPCoefficients[14] = MULT16_16_P15(qLPCoefficients[14], GAMMA_E5);
193: 			weightedqLPCoefficients[15] = MULT16_16_P15(qLPCoefficients[15], GAMMA_E6);
194: 			weightedqLPCoefficients[16] = MULT16_16_P15(qLPCoefficients[16], GAMMA_E7);
195: 			weightedqLPCoefficients[17] = MULT16_16_P15(qLPCoefficients[17], GAMMA_E8);
196: 			weightedqLPCoefficients[18] = MULT16_16_P15(qLPCoefficients[18], GAMMA_E9);
197: 			weightedqLPCoefficients[19] = MULT16_16_P15(qLPCoefficients[19], GAMMA_E10);
198: 
199: 			/*** Compute weighted signal according to spec A3.3.3, this function also compute LPResidualSignal(entire frame values) as specified in eq A.3 ***/
200: 			computeWeightedSpeech(encoderChannelContext->signalCurrentFrame, qLPCoefficients, weightedqLPCoefficients, &(encoderChannelContext->weightedInputSignal[MAXIMUM_INT_PITCH_DELAY]), residualSignal); /* weightedInputSignal contains MAXIMUM_INT_PITCH_DELAY values from previous frame, points to current frame */
201: 
202: 			/* update the target Signal : targetSignal = residualSignal - excitationVector */
203: 			for (subframeIndex=0; subframeIndex<L_FRAME; subframeIndex+=L_SUBFRAME) {
204: 				for (i=0; i<L_SUBFRAME; i++) {
205: 					encoderChannelContext->targetSignal[NB_LSP_COEFF+i] = SUB16(residualSignal[subframeIndex+i], encoderChannelContext->excitationVector[L_PAST_EXCITATION+subframeIndex+i]);
206: 				}
207: 				synthesisFilter(&(encoderChannelContext->targetSignal[NB_LSP_COEFF]), &(weightedqLPCoefficients[LPCoefficientsIndex]), &(encoderChannelContext->targetSignal[NB_LSP_COEFF]));
208: 				LPCoefficientsIndex+= NB_LSP_COEFF;
209: 			}
210: 
211: 			/***  memory updates                                                        ***/
212: 			/* shift left by L_FRAME the signal buffer */
213: 			memmove(encoderChannelContext->signalBuffer, &(encoderChannelContext->signalBuffer[L_FRAME]), (L_LP_ANALYSIS_WINDOW-L_FRAME)*sizeof(word16_t));
214: 			/* shift left by L_FRAME the weightedInputSignal buffer */
215: 			memmove(encoderChannelContext->weightedInputSignal, &(encoderChannelContext->weightedInputSignal[L_FRAME]), MAXIMUM_INT_PITCH_DELAY*sizeof(word16_t));
216: 			/* shift left by L_FRAME the excitationVector */
217: 			memmove(encoderChannelContext->excitationVector, &(encoderChannelContext->excitationVector[L_FRAME]), L_PAST_EXCITATION*sizeof(word16_t));
218: 
219: 			return;
220: 		}
221: 	}
222: 
223: 	/* set generated bitStream length: active voice is compressed into 80 bits */
224: 	*bitStreamLength = 10;
225: 
226: 	/*********** VAD *****************/
227: 
228: 
229: 
230: 
231: 
232: 	/*** LSPQuantization and compute L0, L1, L2, L3: the first four parameters ***/
233: 	LSPQuantization(encoderChannelContext, LSPCoefficients, qLSPCoefficients, parameters);
234: 	
235: 	/*** interpolate qLSP and convert to LP ***/
236: 	interpolateqLSP(encoderChannelContext->previousqLSPCoefficients, qLSPCoefficients, interpolatedqLSP);
237: 	/* copy the currentqLSP to previousqLSP buffer */
238: 	for (i=0; i<NB_LSP_COEFF; i++) {
239: 		encoderChannelContext->previousqLSPCoefficients[i] = qLSPCoefficients[i];
240: 	}
241: 
242: 	/* first subframe */
243: 	qLSP2LP(interpolatedqLSP, qLPCoefficients);
244: 	/* second subframe */
245: 	qLSP2LP(qLSPCoefficients, &(qLPCoefficients[NB_LSP_COEFF]));
246: 
247: 	/*** Compute the weighted Quantized LP Coefficients according to spec A3.3.3 ***/
248: 	/*  weightedqLPCoefficients[0] = qLPCoefficients[0]*Gamma^(i+1) (i=0..9) with Gamma = 0.75 in Q15 */
249: 	weightedqLPCoefficients[0] = MULT16_16_P15(qLPCoefficients[0], GAMMA_E1);
250: 	weightedqLPCoefficients[1] = MULT16_16_P15(qLPCoefficients[1], GAMMA_E2);
251: 	weightedqLPCoefficients[2] = MULT16_16_P15(qLPCoefficients[2], GAMMA_E3);
252: 	weightedqLPCoefficients[3] = MULT16_16_P15(qLPCoefficients[3], GAMMA_E4);
253: 	weightedqLPCoefficients[4] = MULT16_16_P15(qLPCoefficients[4], GAMMA_E5);
254: 	weightedqLPCoefficients[5] = MULT16_16_P15(qLPCoefficients[5], GAMMA_E6);
255: 	weightedqLPCoefficients[6] = MULT16_16_P15(qLPCoefficients[6], GAMMA_E7);
256: 	weightedqLPCoefficients[7] = MULT16_16_P15(qLPCoefficients[7], GAMMA_E8);
257: 	weightedqLPCoefficients[8] = MULT16_16_P15(qLPCoefficients[8], GAMMA_E9);
258: 	weightedqLPCoefficients[9] = MULT16_16_P15(qLPCoefficients[9], GAMMA_E10);
259: 	weightedqLPCoefficients[10] = MULT16_16_P15(qLPCoefficients[10], GAMMA_E1);
260: 	weightedqLPCoefficients[11] = MULT16_16_P15(qLPCoefficients[11], GAMMA_E2);
261: 	weightedqLPCoefficients[12] = MULT16_16_P15(qLPCoefficients[12], GAMMA_E3);
262: 	weightedqLPCoefficients[13] = MULT16_16_P15(qLPCoefficients[13], GAMMA_E4);
263: 	weightedqLPCoefficients[14] = MULT16_16_P15(qLPCoefficients[14], GAMMA_E5);
264: 	weightedqLPCoefficients[15] = MULT16_16_P15(qLPCoefficients[15], GAMMA_E6);
265: 	weightedqLPCoefficients[16] = MULT16_16_P15(qLPCoefficients[16], GAMMA_E7);
266: 	weightedqLPCoefficients[17] = MULT16_16_P15(qLPCoefficients[17], GAMMA_E8);
267: 	weightedqLPCoefficients[18] = MULT16_16_P15(qLPCoefficients[18], GAMMA_E9);
268: 	weightedqLPCoefficients[19] = MULT16_16_P15(qLPCoefficients[19], GAMMA_E10);
269: 
270: 	/*** Compute weighted signal according to spec A3.3.3, this function also set LPResidualSignal(entire frame values) as specified in eq A.3 in excitationVector[L_PAST_EXCITATION] ***/
271: 	computeWeightedSpeech(encoderChannelContext->signalCurrentFrame, qLPCoefficients, weightedqLPCoefficients, &(encoderChannelContext->weightedInputSignal[MAXIMUM_INT_PITCH_DELAY]), &(encoderChannelContext->excitationVector[L_PAST_EXCITATION])); /* weightedInputSignal contains MAXIMUM_INT_PITCH_DELAY values from previous frame, points to current frame  */
272: 
273: 	/*** find the open loop pitch delay ***/
274: 	openLoopPitchDelay = findOpenLoopPitchDelay(&(encoderChannelContext->weightedInputSignal[MAXIMUM_INT_PITCH_DELAY]));
275: 
276: 	/* define boundaries for closed loop pitch delay search as specified in 3.7 */
277: 	intPitchDelayMin = openLoopPitchDelay-3;
278: 	if (intPitchDelayMin < 20) {
279: 		intPitchDelayMin = 20;
280: 	}
281: 	intPitchDelayMax = intPitchDelayMin + 6;
282: 	if (intPitchDelayMax > MAXIMUM_INT_PITCH_DELAY) {
283: 		intPitchDelayMax = MAXIMUM_INT_PITCH_DELAY;
284: 		intPitchDelayMin = MAXIMUM_INT_PITCH_DELAY - 6;
285: 	}
286: 
287: 	/*****************************************************************************************/
288: 	/* loop over the two subframes: Closed-loop pitch search(adaptative codebook), fixed codebook, memory update */
289: 	/* set index and buffers */
290: 	impulseResponseInput[0] = ONE_IN_Q12;
291: 	memset(&(impulseResponseInput[1]), 0, (L_SUBFRAME-1)*sizeof(word16_t));
292: 
293: 	for (subframeIndex=0; subframeIndex<L_FRAME; subframeIndex+=L_SUBFRAME) {
294: 		int16_t intPitchDelay, fracPitchDelay;
295: 		word16_t adaptativeCodebookGain;
296: 		/*** Compute the impulse response : filter a subframe long buffer filled with unit and only zero through the 1/weightedqLPCoefficients as in spec A.3.5 ***/
297: 		word16_t impulseResponseBuffer[NB_LSP_COEFF+L_SUBFRAME]; /* impulseResponseBuffer in Q12, need NB_LSP_COEFF as past value to go through filtering function */
298: 		word16_t filteredAdaptativeCodebookVector[NB_LSP_COEFF+L_SUBFRAME]; /* in Q0, the first NB_LSP_COEFF words are set to zero and used by filter only */
299: 		word64_t gainQuantizationXy, gainQuantizationYy; /* used to store in Q0 values reused in gain quantization */
300: 		word16_t fixedCodebookVector[L_SUBFRAME]; /* in Q13 */
301: 		word16_t convolvedFixedCodebookVector[L_SUBFRAME]; /* in Q12 */
302: 		word16_t quantizedAdaptativeCodebookGain; /* in Q14 */
303: 		word16_t quantizedFixedCodebookGain; /* in Q1 */
304: 
305: 		memset(impulseResponseBuffer, 0, (NB_LSP_COEFF)*sizeof(word16_t)); /* set the past values to zero */
306: 		synthesisFilter(impulseResponseInput, &(weightedqLPCoefficients[LPCoefficientsIndex]), &(impulseResponseBuffer[NB_LSP_COEFF]));
307: 	
308: 		/*** Compute the target signal (x[n]) as in spec A.3.6 in Q0 ***/
309: 		/* excitationVector[L_PAST_EXCITATION+subframeIndex] currently store in Q0 the LPResidualSignal as in spec A.3.3 eq A.3*/
310: 		synthesisFilter( &(encoderChannelContext->excitationVector[L_PAST_EXCITATION+subframeIndex]), &(weightedqLPCoefficients[LPCoefficientsIndex]), &(encoderChannelContext->targetSignal[NB_LSP_COEFF]));
311: 
312: 		/*** Adaptative Codebook search : compute the intPitchDelay, fracPitchDelay and associated parameter, compute also the adaptative codebook vector used to generate the excitation ***/
313: 		/* after this call, the excitationVector[L_PAST_EXCITATION + subFrameIndex] contains the adaptative codebook vector as in spec 3.7.1 */
314: 		adaptativeCodebookSearch(&(encoderChannelContext->excitationVector[L_PAST_EXCITATION + subframeIndex]), &intPitchDelayMin, &intPitchDelayMax, &(impulseResponseBuffer[NB_LSP_COEFF]), &(encoderChannelContext->targetSignal[NB_LSP_COEFF]),
315: 			&intPitchDelay, &fracPitchDelay, &(parameters[parametersIndex]), subframeIndex);
316: 
317: 		/*** Compute adaptative codebook gain spec 3.7.3, result in Q14 ***/
318: 		/* compute the filtered adaptative codebook vector spec 3.7.3 */
319: 		/* this computation makes use of two partial results used for gainQuantization too (yy and xy in eq63), they are part of the function output */
320: 		/* note spec 3.7.3 eq44 make use of convolution of impulseResponse and adaptative codebook vector to compute the filtered version */
321: 		/* in the Annex A, the filter being simpler, it's faster to directly filter the the vector using the  weightedqLPCoefficients */
322: 		memset(filteredAdaptativeCodebookVector, 0, NB_LSP_COEFF*sizeof(word16_t));
323: 		synthesisFilter(&(encoderChannelContext->excitationVector[L_PAST_EXCITATION + subframeIndex]), &(weightedqLPCoefficients[LPCoefficientsIndex]), &(filteredAdaptativeCodebookVector[NB_LSP_COEFF]));
324: 
325: 		adaptativeCodebookGain = computeAdaptativeCodebookGain(&(encoderChannelContext->targetSignal[NB_LSP_COEFF]), &(filteredAdaptativeCodebookVector[NB_LSP_COEFF]), &gainQuantizationXy, &gainQuantizationYy); /* gain in Q14 */
326: 		
327: 		/* increase parameters index and compute P0 if needed */
328: 		parametersIndex++;
329: 		if (subframeIndex==0) { /* first subframe compute P0, the parity bit of P1 */
330: 			parameters[parametersIndex] = computeParity(parameters[parametersIndex-1]);
331: 			parametersIndex++;
332: 		}
